  ).pipe(
    catchError((error) => {
      if (error?.status === 404) {
        return throwError(() => new Error(
          'Restore endpoint not available in the running medical-record service. Restart the medical-record backend and try again.',
        ));
      }

      return throwError(() => error);
    }),
  );
}

